// Lotus v2 static cost, fees and the fee-aware builder against the Lotus
// reference.
//
// Sources:
// - fixtures/lotus-v2/fee_vectors.json: the shared wallet fee vectors,
//   copied unchanged from the Lotus repository
//   tools/lotus-v2-reference/vectors/fee_vectors.json at ce00978506
//   ("reference: shared wallet fee vectors", sha256 07b26536...4701d9),
//   generated by gen_fee_vectors.py beside it from a working tree with
//   uncommitted reference files (coin.py, legacy.py, monetary.py FeeIndex).
//   23 transactions run in the reference VM; Python blake3 1.0.11.
// - fixtures/lotus-v2/fee-vectors-keyhash.json: spends of Frank's keyhash
//   program, which the shared file lacks. The transactions come from
//   lotus-v2-fee-cases.ts; every number from the same reference checkout
//   through scripts/lotus-v2-fee-vectors.py (file hashes recorded inside).
// Rulings applied (lotus-86, 2026-11-19): C_tx by the reference size pass;
// cuShare = 2*ceil(ceil(C_tx*M/2^32)*sqrt(I_n)) + 2*(Q_up(base+C_tx) -
// Q_floor(base)); total = max(IndexedByteFee, tokenBurn + cuShare).

import { readFileSync } from 'node:fs'
import { join } from 'node:path'

import {
  LOTUS_V2_REGTEST,
  LOTUS_V2_REGTEST_NODE_FEE_RULE,
  LOTUS_V2_SPEC_FEE_RULE,
  LotusV2FeeCeilingError,
  LotusV2FormatError,
  LotusV2InsufficientFundsError,
  LotusV2UnsupportedError,
  buildLotusV2Transaction,
  decodeLotusV2CoinOutput,
  decodeLotusV2Transaction,
  encodeLotusV2Transaction,
  lotusV2BranchLeaf,
  lotusV2ByteFee,
  lotusV2IndexedByteFee,
  lotusV2InvocationCost,
  lotusV2Isqrt,
  lotusV2KeyhashProgram,
  lotusV2PublicKeyProgram,
  lotusV2PublicKeyTemplate,
  lotusV2RequiredFee,
  lotusV2StaticCost,
  type LotusV2ChainDescriptor,
  type LotusV2Coin,
  type LotusV2FeeChainState,
  type LotusV2IndexedCuShareRule,
  type LotusV2TemplateSpend,
} from '../src/lotus-v2'
import {
  feeCaseSigner,
  feeCaseWire,
  feeCaseXOnly,
  feeCases,
  keyhashOutput,
  keyhashSpend,
} from './lotus-v2-fee-cases'

const fixture = (name: string) =>
  JSON.parse(
    readFileSync(join(__dirname, 'fixtures', 'lotus-v2', name), 'utf8'),
  )
const hex = (b: Uint8Array): string => Buffer.from(b).toString('hex')
const unhex = (s: string): Uint8Array => Uint8Array.from(Buffer.from(s, 'hex'))

interface SharedIndex {
  subsidy: string
  parent_work: string
}
interface SharedVector {
  name: string
  transaction_kind: string
  base_cost_cu: string
  size_bytes: number
  transaction_hex: string
  spent_coins: { kind: 'v2' | 'legacy' | 'mint'; coin_output_hex?: string }[]
  cost: {
    invocation_charges_cu: number[]
    linear_cost_cu: number
    transaction_cost_cu: number
  }
  inputs: {
    ema_block_cost: string
    cu_index: SharedIndex
    byte_fee_index: SharedIndex
  }
  byte_fee: { byte_fee_atoms: string }
  cu_share: {
    linear_atoms: string
    q_up_atoms: string
    q_floor_base_atoms: string
    cu_share_atoms: string
  }
  token_outputs: number
  token_burn_atoms: string
  recommended_fee_atoms: string
  fee_paid_atoms: string
}

const shared = fixture('fee_vectors.json') as {
  profile: {
    chain_id: string
    genesis_tail: string
    genesis_work: string
    dust_limit: number
    min_fee_per_kb: number
  }
  vectors: SharedVector[]
}
// The vectors sign under their own ChainID; nothing else differs from regtest.
const sharedChain: LotusV2ChainDescriptor = {
  ...LOTUS_V2_REGTEST,
  chainId: shared.profile.chain_id,
}
const ruleC: LotusV2IndexedCuShareRule = {
  ...LOTUS_V2_SPEC_FEE_RULE,
  marginBasisPoints: 0n,
}
const index = (i: SharedIndex) => ({
  subsidy: BigInt(i.subsidy),
  work: BigInt(i.parent_work),
})
const sharedState = (v: SharedVector): LotusV2FeeChainState => ({
  ema: BigInt(v.inputs.ema_block_cost),
  byteFeeIndex: index(v.inputs.byte_fee_index),
  cuIndex: index(v.inputs.cu_index),
  blockCostCu: BigInt(v.base_cost_cu),
})
const sharedCoins = (v: SharedVector): (LotusV2Coin | undefined)[] =>
  v.spent_coins.map(c =>
    c.kind === 'mint'
      ? undefined
      : decodeLotusV2CoinOutput(unhex(c.coin_output_hex as string)),
  )

describe('Lotus v2 fee vectors shared with the Lotus reference', () => {
  test('the profile is the spec rule (c) profile', () => {
    expect(BigInt(shared.profile.genesis_tail)).toBe(ruleC.anchors.genesisTail)
    expect(BigInt(shared.profile.genesis_work)).toBe(ruleC.anchors.genesisWork)
    expect(BigInt(shared.profile.dust_limit)).toBe(ruleC.dustLimit)
    expect(BigInt(shared.profile.min_fee_per_kb)).toBe(ruleC.minFeePerKb)
    expect(shared.vectors).toHaveLength(23)
  })

  test.each(shared.vectors.map(v => [v.name, v] as const))('%s', (_name, v) => {
    const tx = decodeLotusV2Transaction(sharedChain, unhex(v.transaction_hex))
    const coins = sharedCoins(v)
    const cost = lotusV2StaticCost(sharedChain, tx, coins)
    expect(cost.size).toBe(v.size_bytes)
    expect(cost.invocationCosts.flat().map(Number)).toEqual(
      v.cost.invocation_charges_cu,
    )
    expect(cost.linearCost).toBe(BigInt(v.cost.linear_cost_cu))
    expect(cost.transactionCost).toBe(BigInt(v.cost.transaction_cost_cu))
    const fee = lotusV2RequiredFee({
      chain: sharedChain,
      tx,
      rule: ruleC,
      coins,
      state: sharedState(v),
    })
    expect(fee.byteFloor).toBe(BigInt(v.byte_fee.byte_fee_atoms))
    expect(fee.tokenOutputs).toBe(v.token_outputs)
    expect(fee.tokenBurn).toBe(BigInt(v.token_burn_atoms))
    expect(fee.cuShare).toBe(2n * BigInt(v.cu_share.linear_atoms))
    expect(fee.qShare).toBe(
      2n *
        (BigInt(v.cu_share.q_up_atoms) - BigInt(v.cu_share.q_floor_base_atoms)),
    )
    expect(fee.cuShare + fee.qShare).toBe(BigInt(v.cu_share.cu_share_atoms))
    expect(fee.margin).toBe(0n)
    expect(fee.total).toBe(BigInt(v.recommended_fee_atoms))
    expect(fee.total).toBe(BigInt(v.fee_paid_atoms))
    expect(fee.pending).toContain('state-key-weight')
  })

  // Every payment vector pays exactly its recommended fee with change last,
  // so the builder must reproduce its bytes.
  const payments = shared.vectors.filter(v =>
    v.transaction_kind.startsWith('payment-'),
  )
  test.each(payments.map(v => [v.name, v] as const))(
    'the builder reproduces %s byte for byte',
    (_name, v) => {
      const tx = decodeLotusV2Transaction(sharedChain, unhex(v.transaction_hex))
      const coins = sharedCoins(v)
      const inputs: LotusV2TemplateSpend[] = tx.inputs.map((input, i) => {
        if (input.kind !== 'spend') throw new Error('spend')
        const coin = coins[i]
        if (coin === undefined || 'scriptPubKey' in coin)
          throw new Error('v2 coin')
        const key = [1, 2, 3, 4].find(
          k =>
            hex(
              lotusV2BranchLeaf(
                sharedChain,
                lotusV2PublicKeyProgram(feeCaseXOnly(k)),
              ),
            ) === hex(coin.branches[0] as Uint8Array),
        )
        if (key === undefined) throw new Error('no vector key locks this coin')
        return {
          prevTxid: input.prevTxid,
          prevIndex: input.prevIndex,
          sequence: input.sequence,
          coin,
          template: lotusV2PublicKeyTemplate(feeCaseXOnly(key)),
          signer: feeCaseSigner(key),
        }
      })
      const change = tx.outputs[tx.outputs.length - 1]!
      const built = buildLotusV2Transaction({
        chain: sharedChain,
        inputs,
        outputs: tx.outputs.slice(0, -1),
        change: { branches: change.branches, paths: change.paths },
        rule: ruleC,
        state: sharedState(v),
        maxFee: 10_000_000n,
        lock: tx.lock,
      })
      expect(built.fee).toBe(BigInt(v.recommended_fee_atoms))
      expect(built.change).toEqual({
        index: tx.outputs.length - 1,
        value: change.value,
      })
      expect(hex(built.signed.raw)).toBe(v.transaction_hex)
    },
  )
})

interface KeyhashVectors {
  anchors: { genesisTail: string; genesisWork: string }
  states: {
    name: string
    ema: string
    byteFeeIndex: { subsidy: string; work: string }
    cuIndex?: { subsidy: string; work: string }
    blockCostCu?: string
  }[]
  cases: {
    name: string
    tx: string
    coins: string[]
    size: number
    invocationCosts: string[][]
    linearCost: string
    transactionCost: string
    byteFee: string
    tokenOutputs: number
    tokenBurn: string
    priced: {
      state: string
      indexedByteFee: string
      cuShare: string
      qShare: string
      total: string
    }[]
  }[]
}
const keyhash = fixture('fee-vectors-keyhash.json') as KeyhashVectors
const keyhashStates: LotusV2FeeChainState[] = keyhash.states.map(s => ({
  ema: BigInt(s.ema),
  byteFeeIndex: {
    subsidy: BigInt(s.byteFeeIndex.subsidy),
    work: BigInt(s.byteFeeIndex.work),
  },
  ...(s.cuIndex
    ? {
        cuIndex: {
          subsidy: BigInt(s.cuIndex.subsidy),
          work: BigInt(s.cuIndex.work),
        },
      }
    : {}),
  ...(s.blockCostCu ? { blockCostCu: BigInt(s.blockCostCu) } : {}),
}))

describe('Lotus v2 fee vectors for the keyhash program (reference-generated)', () => {
  const chain = LOTUS_V2_REGTEST
  test('the cases module still builds the recorded transactions', () => {
    expect(feeCases().map(c => ({ name: c.name, ...feeCaseWire(c) }))).toEqual(
      keyhash.cases.map(c => ({ name: c.name, tx: c.tx, coins: c.coins })),
    )
    expect(BigInt(keyhash.anchors.genesisTail)).toBe(ruleC.anchors.genesisTail)
    expect(BigInt(keyhash.anchors.genesisWork)).toBe(ruleC.anchors.genesisWork)
  })

  test.each(keyhash.cases.map(c => [c.name, c] as const))('%s', (_name, c) => {
    const tx = decodeLotusV2Transaction(chain, unhex(c.tx))
    const coins = c.coins.map(h => decodeLotusV2CoinOutput(unhex(h)))
    const cost = lotusV2StaticCost(chain, tx, coins)
    expect(cost.size).toBe(c.size)
    expect(cost.invocationCosts.map(ws => ws.map(String))).toEqual(
      c.invocationCosts,
    )
    expect(cost.linearCost).toBe(BigInt(c.linearCost))
    expect(cost.transactionCost).toBe(BigInt(c.transactionCost))
    const node = lotusV2RequiredFee({
      chain,
      tx,
      rule: LOTUS_V2_REGTEST_NODE_FEE_RULE,
    })
    expect(node.byteFloor).toBe(BigInt(c.byteFee))
    expect(node.tokenBurn).toBe(BigInt(c.tokenBurn))
    keyhashStates.forEach((state, i) => {
      const expected = c.priced[i]!
      const fee = lotusV2RequiredFee({ chain, tx, rule: ruleC, coins, state })
      expect(fee.byteFloor).toBe(BigInt(expected.indexedByteFee))
      expect(fee.cuShare).toBe(BigInt(expected.cuShare))
      expect(fee.qShare).toBe(BigInt(expected.qShare))
      expect(fee.total).toBe(BigInt(expected.total))
    })
  })
})

describe('Lotus v2 static cost units', () => {
  test('the approved invocation charges of the single-signature programs', () => {
    // resources.type1_invocation(): 34 structural + PUSH32 2 + BIP340 210.
    expect(
      lotusV2InvocationCost(lotusV2PublicKeyProgram(feeCaseXOnly(1)), [64]),
    ).toBe(246n)
    // DUP 2, BLAKE3 3, PUSH32 2, EQUALVERIFY 2, CHECKSIG 210, 37 structural.
    expect(
      lotusV2InvocationCost(
        lotusV2KeyhashProgram(new Uint8Array(32)),
        [64, 32],
      ),
    ).toBe(256n)
  })

  test('opcodes the size pass is not implemented for are explicit errors', () => {
    // ADD (0x98) is outside the implemented subset.
    expect(() =>
      lotusV2InvocationCost(Uint8Array.of(0x51, 0x51, 0x98), []),
    ).toThrow(LotusV2UnsupportedError)
    // A loop.
    expect(() =>
      lotusV2InvocationCost(Uint8Array.of(0x51, 0x69, 0x79, 0x6a), []),
    ).toThrow(LotusV2UnsupportedError)
  })

  test('an underflowing instruction charges the maximum from there on', () => {
    // DUP on an empty stack: Unknown, then every operand at 8192 bytes.
    const known = lotusV2InvocationCost(Uint8Array.of(0x7a), [1])
    const unknown = lotusV2InvocationCost(Uint8Array.of(0x7a), [])
    expect(known).toBe(1n + 2n)
    expect(unknown).toBe(1n + BigInt(1 + Math.ceil((10 * 8192) / 1024)))
  })

  test('both arms of a conditional are bounded by the larger', () => {
    // IF BLAKE3 ELSE DROP ENDIF on [32, 1]: IF 2 + ENDIF 1 + ELSE 1 + max(3, 2).
    const cost = lotusV2InvocationCost(
      Uint8Array.of(0x61, 0xba, 0x63, 0x79, 0x64),
      [32, 1],
    )
    expect(cost).toBe(5n + 2n + 1n + 1n + 3n)
  })

  test('integer square root and the byte fees', () => {
    for (const n of [
      0n,
      1n,
      2n,
      3n,
      4n,
      15n,
      16n,
      17n,
      (1n << 200n) + 12345n,
    ]) {
      const r = lotusV2Isqrt(n)
      expect(r * r <= n && (r + 1n) * (r + 1n) > n).toBe(true)
    }
    expect(lotusV2ByteFee(251)).toBe(251n)
    expect(lotusV2ByteFee(1, 1500n)).toBe(2n)
    const anchors = ruleC.anchors
    const at = (subsidy: bigint, work: bigint) =>
      lotusV2IndexedByteFee(250, { subsidy, work }, anchors)
    const T = anchors.genesisTail
    const W = anchors.genesisWork
    expect(at(T, W)).toBe(250n)
    expect(at(4n * T, W)).toBe(500n)
    expect(at(2n * T, W)).toBe(354n) // ceil(250 * sqrt 2)
  })
})

describe('Lotus v2 fees under the rule lotusd v0.34.1 enforces', () => {
  test('byte floor and token burn, never added together', () => {
    const chain = LOTUS_V2_REGTEST
    for (const c of feeCases()) {
      const raw = unhex(feeCaseWire(c).tx)
      const tx = decodeLotusV2Transaction(chain, raw)
      const fee = lotusV2RequiredFee({
        chain,
        tx,
        rule: LOTUS_V2_REGTEST_NODE_FEE_RULE,
      })
      const tokens = tx.outputs.filter(o => o.tokenId).length
      expect(fee.total).toBe(BigInt(Math.max(raw.length, 2 * 546 * tokens)))
      expect(fee.cuShare + fee.qShare + fee.margin).toBe(0n)
    }
  })

  test('rule (c) without chain state is refused', () => {
    const chain = LOTUS_V2_REGTEST
    const tx = decodeLotusV2Transaction(
      chain,
      unhex(feeCaseWire(feeCases()[0]!).tx),
    )
    expect(() => lotusV2RequiredFee({ chain, tx, rule: ruleC })).toThrow(
      /chain state/,
    )
  })
})

describe('Lotus v2 fee-aware builder', () => {
  const chain = LOTUS_V2_REGTEST
  const change = keyhashOutput(1, 0n)
  const destination = { branches: change.branches, paths: change.paths }
  const quiet = keyhashStates[0]!

  test('pays the exact fee of the final transaction and returns the change', () => {
    for (const rule of [
      LOTUS_V2_REGTEST_NODE_FEE_RULE,
      LOTUS_V2_SPEC_FEE_RULE,
    ]) {
      const built = buildLotusV2Transaction({
        chain,
        inputs: [keyhashSpend(1, 0, 10_000_000n)],
        outputs: [keyhashOutput(2, 3_000_000n)],
        change: destination,
        rule,
        state: quiet,
        maxFee: 1_000_000n,
      })
      const again = lotusV2RequiredFee({
        chain,
        tx: built.signed.transaction,
        rule,
        coins: [keyhashSpend(1, 0, 10_000_000n).coin],
        state: quiet,
      })
      expect(built.fee).toBe(again.total)
      expect(built.breakdown).toEqual(again)
      expect(built.change?.value).toBe(10_000_000n - 3_000_000n - built.fee)
      expect(built.droppedChange).toBe(0n)
      expect(encodeLotusV2Transaction(chain, built.signed.transaction)).toEqual(
        built.signed.raw,
      )
    }
    // Rule (c) at the quiet calibration point: the keyhash 1-in/2-out vector
    // plus the 2% margin on the cu share.
    const priced = keyhash.cases[0]!.priced[0]!
    const share = BigInt(priced.cuShare) + BigInt(priced.qShare)
    const built = buildLotusV2Transaction({
      chain,
      inputs: [keyhashSpend(1, 0, 10_000_000n)],
      outputs: [keyhashOutput(2, 3_000_000n)],
      change: destination,
      rule: LOTUS_V2_SPEC_FEE_RULE,
      state: quiet,
      maxFee: 1_000_000n,
    })
    expect(built.fee).toBe(share + (share * 200n + 9999n) / 10000n)
  })

  test('change below DUST_LIMIT goes to the fee', () => {
    // 1-in/1-out keyhash: 242 bytes; 1-in/2-out: 287 bytes.
    const value = 3_000_000n
    const built = buildLotusV2Transaction({
      chain,
      inputs: [keyhashSpend(1, 0, value + 287n + 545n)],
      outputs: [keyhashOutput(2, value)],
      change: destination,
      rule: LOTUS_V2_REGTEST_NODE_FEE_RULE,
      maxFee: 10_000n,
    })
    expect(built.change).toBeUndefined()
    expect(built.signed.transaction.outputs).toHaveLength(1)
    expect(built.breakdown.total).toBe(242n)
    expect(built.fee).toBe(287n + 545n)
    expect(built.droppedChange).toBe(287n + 545n - 242n)
    // One more atom and the change output exists at exactly DUST_LIMIT.
    const withChange = buildLotusV2Transaction({
      chain,
      inputs: [keyhashSpend(1, 0, value + 287n + 546n)],
      outputs: [keyhashOutput(2, value)],
      change: destination,
      rule: LOTUS_V2_REGTEST_NODE_FEE_RULE,
      maxFee: 10_000n,
    })
    expect(withChange.change?.value).toBe(546n)
    expect(withChange.fee).toBe(287n)
  })

  test('the caller ceiling, missing funds and dust outputs are refused', () => {
    const base = {
      chain,
      inputs: [keyhashSpend(1, 0, 10_000_000n)],
      outputs: [keyhashOutput(2, 3_000_000n)],
      change: destination,
      rule: LOTUS_V2_SPEC_FEE_RULE,
      state: quiet,
    }
    expect(() => buildLotusV2Transaction({ ...base, maxFee: 100n })).toThrow(
      LotusV2FeeCeilingError,
    )
    expect(() =>
      buildLotusV2Transaction({
        ...base,
        outputs: [keyhashOutput(2, 9_999_000n)],
        maxFee: 1_000_000n,
      }),
    ).toThrow(LotusV2InsufficientFundsError)
    expect(() =>
      buildLotusV2Transaction({
        ...base,
        outputs: [keyhashOutput(2, 545n)],
        maxFee: 1_000_000n,
      }),
    ).toThrow(LotusV2FormatError)
    // Sub-dust change dropped into the fee still counts against the ceiling.
    expect(() =>
      buildLotusV2Transaction({
        ...base,
        inputs: [keyhashSpend(1, 0, 3_000_000n + 287n + 545n)],
        rule: LOTUS_V2_REGTEST_NODE_FEE_RULE,
        maxFee: 300n,
      }),
    ).toThrow(LotusV2FeeCeilingError)
  })
})
